  color: var(--text-light);
}

.store-distance {
  font-family: 'Nunito', sans-serif;
  font-weight: 700;
  color: var(--accent);
  font-size: 1.125rem;
  white-space: nowrap;
}

/* Newsletter */
.newsletter {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  padding: 5rem 2rem;
  text-align: center;
}

.newsletter-content {
  max-width: 600px;
  margin: 0 auto;
}

.newsletter-title {
  font-size: 2.5rem;
  color: var(--white);
  margin-bottom: 0.75rem;
}

.newsletter-subtitle {
  font-size: 1.1rem;
  color: rgba(255, 255, 255, 0.9);
  margin-bottom: 2rem;
}

.newsletter-form {
  display: flex;
  gap: 1rem;
  max-width: 450px;
  margin: 0 auto 1rem;
}

.newsletter-input {
  flex: 1;
  padding: 1rem 1.5rem;
  border: 2px solid transparent;
  border-radius: 50px;
  font-size: 1rem;
  font-family: inherit;
  background: var(--white);
}

.newsletter-input:focus {
  outline: none;
  border-color: var(--accent);
}

.newsletter-form .btn {
  background: var(--accent);
  color: var(--text);
}

.newsletter-form .btn:hover {
  background: var(--accent-light);
}

.newsletter-confirmation {
  color: var(--white);
  font-weight: 600;
  display: none;
}

.newsletter-confirmation.active {
  display: block;
  animation: fadeIn 0.5s ease;
}

/* Footer */
.footer {
  background: var(--text);
  color: var(--white);
  padding: 4rem 2rem 2rem;
}

.footer-container {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 4rem;
  margin-bottom: 3rem;
}

.footer-brand .logo {
  margin-bottom: 1rem;
}

.footer-brand .logo-text {
  color: var(--white);
}

.footer-brand .logo-icon {
  filter: grayscale(0);
}

.footer-tagline {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.875rem;
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.footer-heading {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent);
  margin-bottom: 1rem;
}

.footer-column {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-link {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.8);
  transition: color 0.3s ease;
}

.footer-link:hover {
  color: var(--accent);
}

.social-links {
  display: flex;
  gap: 1rem;
}

.social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  transition: all 0.3s ease;
}

.social-link:hover {
  background: var(--accent);
  transform: translateY(-3px);
}

.social-link svg {
  width: 20px;
  height: 20px;
  color: var(--white);
}

.footer-bottom {
  max-width: 1280px;
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  text-align: center;
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeInRight {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Responsive */
@media (max-width: 1024px) {
  .hero {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 2rem;
  }

  .hero-content {
    order: 2;
  }

  .hero-image {
    order: 1;
  }

  .hero-subtitle {
    margin: 0 auto 2rem;
  }

  .hero-buttons {
    justify-content: center;
  }

  .highlights-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 3rem 2rem;
  }

  .seasonal-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .category-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-container {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

@media (max-width: 768px) {
  .nav {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .hero-title {
    font-size: 2.5rem;
  }

  .hero-subtitle {
    font-size: 1.1rem;
  }

  .hero-image img {
    height: 280px;
  }

  .section-title {
    font-size: 2rem;
  }

  .carousel-track {
    gap: 1rem;
  }

  .product-card {
    width: 240px;
  }

  .highlight-number {
    font-size: 2.5rem;
  }

  .category-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .store-search {
    flex-direction: column;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .footer-links {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .header-container {
    padding: 1rem;
  }

  .hero {
    padding: 2rem 1rem;
  }

  .hero-title {
    font-size: 2rem;
  }

  .hero-buttons {
    flex-direction: column;
    width: 100%;
  }

  .hero-buttons .btn {
    width: 100%;
  }

  .featured-products,
  .seasonal-picks,
  .categories,
  .store-locator {
    padding: 3rem 1rem;
  }

  .seasonal-grid {
    grid-template-columns: 1fr;
  }

  .category-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1rem;
  }

  .store-result-card {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 1rem;
  }

  .footer-links {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .social-links {
    justify-content: center;
  }
}

raw_arguments.content:
/* Fresh Pantry - Styles */

:root {
  --primary: #2D6A4F;
  --primary-light: #40916C;
  --accent: #F4A261;
  --accent-light: #FFD166;
  --cream: #FEFAE0;
  --white: #FFFFFF;
  --text: #1B4332;
  --text-light: #52796F;
  --shadow: rgba(45, 106, 79, 0.1);
  --radius: 16px;
  --radius-sm: 8px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Open Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--cream);
  color: var(--text);
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Nunito', sans-serif;
  font-weight: 700;
}

a {
  text-decoration: none;
  color: inherit;
}

img {
  max-width: 100%;
  height: auto;
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  box-shadow: 0 2px 20px var(--shadow);
}

.header-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.logo-icon {
  font-size: 2rem;
}

.logo-text {
  font-family: 'Nunito', sans-serif;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.nav {
  display: flex;
  gap: 2rem;
}

.nav-link {
  font-weight: 600;
  color: var(--text);
  padding: 0.5rem 0;
  position: relative;
  transition: color 0.3s ease;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent);
  transition: width 0.3s ease;
}

.nav-link:hover {
  color: var(--primary);
}

.nav-link:hover::after {
  width: 100%;
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 5px;
}

.mobile-menu-btn span {
  display: block;
  width: 25px;
  height: 3px;
  background: var(--primary);
  border-radius: 2px;
  transition: 0.3s;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 1.75rem;
  border-radius: 50px;
  font-family: 'Nunito', sans-serif;
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.3s ease;
  border: 2px solid transparent;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(45, 106, 79, 0.3);
}

.btn-secondary {
  background: transparent;
  color: var(--primary);
  border-color: var(--primary);
}

.btn-secondary:hover {
  background: var(--primary);
  color: var(--white);
}

/* Hero */
.hero {
  max-width: 1280px;
  margin: 0 auto;
  padding: 4rem 2rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.hero-content {
  animation: fadeInUp 0.8s ease;
}

.hero-title {
  font-size: 3.5rem;
  line-height: 1.1;
  color: var(--primary);
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-light);
  margin-bottom: 2rem;
  max-width: 500px;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero-image {
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 20px 60px var(--shadow);
  animation: fadeInRight 0.8s ease;
}

.hero-image img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  display: block;
}

/* Highlights Banner */
.highlights {
  background: var(--primary);
  padding: 3rem 2rem;
}

.highlights-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.highlight-item {
  text-align: center;
  color: var(--white);
}

.highlight-number {
  display: block;
  font-family: 'Nunito', sans-serif;
  font-size: 3rem;
  font-weight: 800;
  color: var(--accent);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.highlight-label {
  font-size: 1rem;
  opacity: 0.9;
}

/* Section Headers */
.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

.section-title {
  font-size: 2.5rem;
  color: var(--primary);
  margin-bottom: 0.75rem;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--text-light);
}

/* Featured Products */
.featured-products {
  padding: 5rem 2rem;
  max-width: 1280px;
  margin: 0 auto;
}

.carousel-container {
  position: relative;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.carousel-track-wrapper {
  overflow: hidden;
  flex: 1;
}

.carousel-track {
  display: flex;
  gap: 1.5rem;
  transition: transform 0.4s ease;
  padding: 0.5rem;
}

.carousel-btn {
  flex-shrink: 0;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--primary);
  color: var(--primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s ease;
  z-index: 10;
}

.carousel-btn:hover:not(:disabled) {
  background: var(--primary);
  color: var(--white);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.product-card {
  flex-shrink: 0;
  width: 280px;
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 4px 20px var(--shadow);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.product-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 12px 40px var(--shadow);
}

.product-image {
  height: 180px;
  overflow: hidden;
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.product-card:hover .product-image img {
  transform: scale(1.05);
}

.product-info {
  padding: 1.25rem;
}

.product-name {
  font-size: 1.1rem;
  color: var(--text);
  margin-bottom: 0.5rem;
  line-height: 1.3;
}

.product-desc {
  font-size: 0.875rem;
  color: var(--text-light);
  margin-bottom: 0.75rem;
  line-height: 1.4;
}

.product-price {
  font-family: 'Nunito', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
}

/* Seasonal Picks */
.seasonal-picks {
  background: var(--white);
  padding: 5rem 2rem;
}

.seasonal-picks .section-header {
  max-width: 1280px;
  margin: 0 auto 3rem;
}

.seasonal-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.seasonal-card {
  background: var(--cream);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.seasonal-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 12px 40px var(--shadow);
}

.seasonal-image {
  height: 160px;
  overflow: hidden;
}

.seasonal-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.seasonal-card:hover .seasonal-image img {
  transform: scale(1.05);
}

.seasonal-info {
  padding: 1.25rem;
}

.seasonal-name {
  font-size: 1rem;
  color: var(--text);
  margin-bottom: 0.5rem;
  line-height: 1.3;
}

.seasonal-desc {
  font-size: 0.875rem;
  color: var(--text-light);
  margin-bottom: 0.75rem;
}

.seasonal-price {
  font-family: 'Nunito', sans-serif;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--accent);
}

/* Categories */
.categories {
  padding: 5rem 2rem;
  max-width: 1280px;
  margin: 0 auto;
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1.5rem;
}

.category-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  aspect-ratio: 4/5;
}

.category-image {
  width: 100%;
  height: 100%;
}

.category-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.category-card:hover .category-image img {
  transform: scale(1.1);
}

.category-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(45, 106, 79, 0.9) 0%, rgba(45, 106, 79, 0.4) 50%, transparent 100%);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 1.5rem;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.category-card:hover .category-overlay {
  opacity: 1;
}

.category-card:hover {
  transform: scale(1.03);
  transition: transform 0.3s ease;
}

.category-name {
  font-size: 1.25rem;
  color: var(--white);
  text-align: center;
}

/* Store Locator */
.store-locator {
  background: var(--white);
  padding: 5rem 2rem;
}

.store-locator .section-header {
  max-width: 1280px;
  margin: 0 auto 2rem;
}

.store-search {
  max-width: 600px;
