  .hero-image {
    order: 1;
  }

  .hero-subtitle {
    margin: 0 auto 2rem;
  }

  .hero-buttons {
    justify-content: center;
  }

  .highlights-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 3rem 2rem;
  }

  .seasonal-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .category-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .footer-container {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

@media (max-width: 768px) {
  .nav {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .hero-title {
    font-size: 2.5rem;
  }

  .hero-subtitle {
    font-size: 1.1rem;
  }

  .hero-image img {
    height: 280px;
  }

  .section-title {
    font-size: 2rem;
  }

  .carousel-track {
    gap: 1rem;
  }

  .product-card {
    width: 240px;
  }

  .highlight-number {
    font-size: 2.5rem;
  }

  .category-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .store-search {
    flex-direction: column;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .footer-links {
    grid-template-columns: repeat(2, 1fr);
  }
