@media (max-width: 480px) {
  .header-container {
    padding: 1rem;
  }

  .hero {
    padding: 2rem 1rem;
  }

  .hero-title {
    font-size: 2rem;
  }

  .hero-buttons {
    flex-direction: column;
    width: 100%;
  }

  .hero-buttons .btn {
    width: 100%;
  }

  .featured-products,
  .seasonal-picks,
  .categories,
