  .category-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1rem;
  }

  .store-result-card {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 1rem;
  }

  .footer-links {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .social-links {
    justify-content: center;
  }
}

